export type FreelancerSkillStatus = "approved" | "pending_review" | "rejected";

export interface FreelancerSkillDefinition {
  skillId: string;
  arabicName: string;
  englishName: string;
  category: FreelancerSkillCategory;
  status: FreelancerSkillStatus;
  aliases: string[];
  searchableText: string;
}

export interface FreelancerCustomSkillSuggestion {
  suggestionId: string;
  rawLabel: string;
  normalizedLabel: string;
  suggestedByUserId?: string;
  suggestedByPhone?: string;
  status: "pending_review" | "approved" | "rejected";
  matchedExistingSkillId?: string;
  adminNote?: string;
  createdAt: string;
  reviewedAt?: string;
  reviewedBy?: string;
}

function normalizeSkillText(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[إأآا]/g, "ا")
    .replace(/[ىي]/g, "ي")
    .replace(/[ة]/g, "ه")
    .replace(/\s+/g, " ");
}

function makeSkill(
  skillId: string,
  arabicName: string,
  englishName: string,
  category: FreelancerSkillCategory,
  aliases: string[] = [],
): FreelancerSkillDefinition {
  const searchableText = [skillId, arabicName, englishName, ...aliases]
    .map(normalizeSkillText)
    .join(" ");
  return { skillId, arabicName, englishName, category, status: "approved", aliases, searchableText };
}

