export function getApprovedFreelancerSkills(): FreelancerSkillDefinition[] {
  return FREELANCER_SKILL_REGISTRY.filter((skill) => skill.status === "approved");
}

export function findFreelancerSkills(query: string): FreelancerSkillDefinition[] {
  const normalized = normalizeSkillText(query);
  if (!normalized) return getApprovedFreelancerSkills();
  return getApprovedFreelancerSkills().filter((skill) => skill.searchableText.includes(normalized));
}

export function findFreelancerSkillsByIds(skillIds: string[]): FreelancerSkillDefinition[] {
  const wanted = new Set(skillIds);
  return getApprovedFreelancerSkills().filter((skill) => wanted.has(skill.skillId));
}

export function makeCustomFreelancerSkillSuggestion(input: {
  rawLabel: string;
  suggestedByUserId?: string;
  suggestedByPhone?: string;
}): FreelancerCustomSkillSuggestion {
  const normalizedLabel = normalizeSkillText(input.rawLabel);
  const matched = findFreelancerSkills(normalizedLabel)[0];
  return {
    suggestionId: `custom-skill-${Date.now()}`,
    rawLabel: input.rawLabel.trim(),
    normalizedLabel,
    suggestedByUserId: input.suggestedByUserId,
    suggestedByPhone: input.suggestedByPhone,
    status: "pending_review",
    matchedExistingSkillId: matched?.skillId,
    createdAt: new Date().toISOString(),
  };
}

export function isValidFreelancerSkillSelection(skillIds: string[]): boolean {
  if (!Array.isArray(skillIds)) return false;
  if (skillIds.length === 0) return false;
  const approvedIds = new Set(getApprovedFreelancerSkills().map((skill) => skill.skillId));
  return skillIds.every((skillId) => approvedIds.has(skillId));
}